[3104] = { en = "Glyphic Letter", tier = 1,
  t = "Een brief met tekens",
  d = "Ik moest je dit zo snel mogelijk geven als je terug was van de kampen van de kobolds, $N. Het lijkt een brief met het zegel van Khelden. Hij is hier de leraar voor magiërs. Ik zou niet twijfelen: lees hem, voordat je iets anders doet hier in de abdij.",
  o = "Lees de Glyphic Letter en praat met Khelden Bremen in Northshire Abbey.",
  p = "Hallo, $N. Ik ben Khelden. Kan ik iets voor je doen?",
  c = "Haha, ik wist wel dat mijn briefje je niet zou tegenhouden. Dus je bent er klaar voor? Ben je klaar om je lot te aanvaarden? Klaar om de goden uit te dagen, en alle andere krachten die voor je staan, op zoek naar kennis en macht?$B$BIk zal niet liegen, $N. Mensen zullen net zo bang voor je zijn als ze je respecteren. Maar weet ook dit: ik ben hier voor je als je training nodig hebt. Zoek me gewoon op als je sterker wordt.",
  g = { {"tekens", "signs, glyphs (teken)"}, {"kampen", "camps (kamp)"}, {"zegel", "seal, insignia"}, {"magiërs", "mages (magiër)"}, {"twijfelen", "hesitate, doubt"}, {"abdij", "abbey"}, {"tegenhouden", "stop, hold back"}, {"lot", "fate"}, {"aanvaarden", "accept"}, {"uit te dagen", "to challenge (uitdagen)"}, {"krachten", "forces (kracht)"}, {"kennis", "knowledge"}, {"macht", "power"}, {"liegen", "lie"} },
