[3111] = { en = "Glyphic Rune", tier = 1,
  t = "Een rune met tekens",
  d = "Lang geleden leerden de hoge elfen ons de geheimen van magie, samen met onze menselijke bondgenoten. Ze preekten tegen ons over regels, en dat magie je gek kan maken! Maar geloof het niet. Wij zijn niet zoals de elfen. Wij hebben niet dezelfde zwakke punten. Blijf gewoon op het goede pad. Dan zie je dat magie een even sterk gereedschap is als een wapen.$B$BAls je klaar bent, kom me dan zoeken in Anvilmar. Ik wacht op je!",
  o = "Praat met Marryk Nurribit in Anvilmar.",
  g = { {"hoge elfen", "high elves"}, {"geheimen", "secrets (geheim)"}, {"menselijke", "human (menselijk)"}, {"bondgenoten", "allies (bondgenoot)"}, {"preekten", "preached (preken)"}, {"gek", "mad, crazy"}, {"zwakke punten", "weaknesses"}, {"pad", "path"}, {"gereedschap", "tool"} },
},

[3114] = { en = "Glyphic Memorandum", tier = 1,
  t = "Een memo met tekens",
  d = "Terwijl je me hielp, kreeg ik deze memo. Ik moest hem aan jou geven. Lees hem als je even tijd hebt. Ik denk dat hij van Marryk komt, de leraar voor magiërs. Kijk er even naar en zoek hem op in Anvilmar als je tijd hebt.",
  o = "Lees het Glyphic Memorandum en praat met Marryk Nurribit in Anvilmar, boven Coldridge Valley.",
  p = "Ja, wat is er, $R? Praat wat harder, als je het niet erg vindt. Na een paar biertjes hoor ik niet zo goed.",
  c = "O, ja! De arcane kunsten... natuurlijk.$b$bDit moet je weten, $N: zorg dat je niet in te veel problemen komt. Spaar wat geld om een biertje voor me te kopen... of spreuken die je wilt hebben. En blijf heel ver weg van Gnomeregan. Verder: een fijne dag! Ik ben hier als je me nodig hebt of wilt trainen... of zo.",
  g = { {"Terwijl", "While"}, {"memo", "memorandum"}, {"magiërs", "mages (magiër)"}, {"Kijk er even naar", "Take a look at it"}, {"harder", "louder"}, {"biertjes", "beers, ales (biertje)"}, {"arcane kunsten", "arcane arts"}, {"Spaar", "Save (sparen)"}, {"spreuken", "spells (spreuk)"}, {"blijf ver weg", "stay away"} },
},

[1860] = { en = "Speak with Jennea", tier = 1,
  t = "Praat met Jennea",
  d = "Wij magiërs hebben een taak die gedaan moet worden. Die taak is heel belangrijk voor de veiligheid van Stormwind en Elwynn Forest.$B$BJennea Cannon weet er meer over. Ze studeert in de Wizard's Sanctum, in de magiërswijk van Stormwind. Ga snel naar haar toe.",
  o = "Praat met Jennea Cannon in Stormwind.",
  c = "Ben je gestuurd om me te helpen met mijn taak, $n? Goed. Het is fijn om jonge magiërs te zien die graag willen helpen met onze zaak...$b$bWelke zaak, vraag je? Later, jongeling. Je zult het weten... later.",
  g = { {"magiërs", "mages (magiër)"}, {"taak", "task"}, {"veiligheid", "safety"}, {"studeert", "studies (studeren)"}, {"magiërswijk", "mage district"}, {"zaak", "cause"}, {"jongeling", "young one"} },
},

[1861] = { en = "Mirror Lake", tier = 1,
  t = "Mirror Lake",
  d = "Deze wereld heeft zware magische gevechten meegemaakt. Daardoor zijn magische stromen uit hun vroeger stabiele kanalen gescheurd. We proberen uit te zoeken wat de gevolgen van die veranderingen zijn, en sommigen van ons vrezen het ergste!$B$BMaar daar vertel ik later meer over. Nu moet jij informatie voor ons verzamelen.$B$BHier, neem deze fles. Ga naar de voet van de waterval bij Mirror Lake, ten zuidwesten van de poorten van Stormwind, en haal daar een monster van het water. Breng het naar mij, zodat ik kan testen of het magisch besmet is.",
  o = "Breng een monster van Mirror Lake naar Jennea Cannon in Stormwind.",
  p = "Heb je het monster, $N? De stroom van magie in Stormwind en Elwynn is veranderd, en ik moet weten of die in het water sijpelt.",
  c = "Bedankt, $N. Ik ga dit water testen op magische eigenschappen. Laten we hopen dat het er geen heeft. Anders merken we misschien dat mensen die te lang uit Mirror Lake drinken er last van krijgen.$B$BHier, $N. Neem deze bol of staf als teken van je dienst. Moge hij je goed dienen.",
  g = { {"gevechten", "struggles, battles (gevecht)"}, {"meegemaakt", "gone through (meemaken)"}, {"stromen", "currents (stroom)"}, {"stabiele", "stable (stabiel)"}, {"kanalen", "channels (kanaal)"}, {"gescheurd", "torn (scheuren)"}, {"gevolgen", "effects, consequences (gevolg)"}, {"vrezen", "fear"}, {"voet", "foot, base"}, {"waterval", "waterfall"}, {"monster", "sample"}, {"besmet", "tainted, contaminated"}, {"sijpelt", "seeps (sijpelen)"}, {"eigenschappen", "properties (eigenschap)"}, {"last van krijgen", "be affected by, suffer from"}, {"bol", "orb"} },
},

[1879] = { en = "Speak with Bink", tier = 1,
  t = "Praat met Bink",
  d = "$N! Bink, mijn collega in Ironforge, een gnoom, stuurt een bericht. Ze heeft een taak die gedaan moet worden, en ze wil alleen een magiër vertrouwen! Ben jij die magiër, $N?$B$BZo ja, praat dan met Bink. Ze is meestal in de Hall of Mysteries in de Mystic Ward van Ironforge.",
  o = "Praat met Bink in Ironforge.",
  c = "O, ik zie dat je talent hebt, jazeker! Maar je hebt meer nodig dan talent om een goede magiër te zijn. En als je geen goede magiër bent, dan ben je een slechte magiër. En slechte magiërs zijn een deel van het probleem, jazeker!$b$bOeps, ik loop op de zaken vooruit. Laten we bij het begin beginnen!",
  g = { {"collega", "colleague"}, {"gnoom", "gnome"}, {"bericht", "message, word"}, {"vertrouwen", "trust, rely on"}, {"Zo ja", "If so"}, {"meestal", "usually"}, {"talent", "promise, talent"}, {"jazeker", "yes indeed"}, {"Oeps", "Oops"}, {"loop op de zaken vooruit", "get ahead of things (vooruitlopen op)"} },
},

[1880] = { en = "Mage-tastic Gizmonitor", tier = 1,
  t = "De Mage-tastic Gizmonitor",
  d = "Wij magiërs doen meer dan met onze vingers wiebelen en mooie vonken maken! We beheersen magie, de stof waar onze wereld uit bestaat! En dat vraagt veel zorg en vastberadenheid. En kennis... zo veel kennis!$B$BEen van mijn apparaten, de mage-tastic gizmonitor, verzamelt die kennis en bewaart er heel veel van! Maar hij is kwijt! Toen we uit ons thuis Gnomeregan vluchtten, liet ik hem achter in een kist in een van onze hutten buiten de stad. En nu krioelt het daar van de melaatse gnomen!$B$BAlsjeblieft, $N, haal mijn gizmonitor terug!",
  o = "Breng Bink haar Mage-tastic Gizmonitor.",
  p = "Heb je de gizmonitor gevonden? Ik moet hem hebben voordat zijn energie op is!",
  c = "O, wat een heerlijke dag! Toen ik de gizmonitor maakte, wist ik niet hoe afhankelijk ik ervan zou worden. Nu kan ik opnieuw beginnen met mijn studie!$B$BBedankt, $N! En hier: dit was mijn eerste gereedschap als $C. Het heeft wat krassen, maar het is goed getest. Kies maar. Je hebt vast iets aan allebei.",
  g = { {"wiebelen", "waggle, wiggle"}, {"vonken", "sparks (vonk)"}, {"beheersen", "control, master"}, {"stof", "fabric, substance"}, {"bestaat", "consists (bestaan uit)"}, {"vastberadenheid", "resolve, determination"}, {"apparaten", "devices (apparaat)"}, {"bewaart", "stores (bewaren)"}, {"vluchtten", "fled (vluchten)"}, {"hutten", "huts (hut)"}, {"krioelt", "is crawling, teems (krioelen)"}, {"melaatse", "leper (melaats)"}, {"afhankelijk", "dependent"}, {"krassen", "scratches (kras)"}, {"getest", "tested (testen)"} },
},

[1919] = { en = "Report to Jennea", tier = 1,
  t = "Meld je bij Jennea",
  d = "Je kennis van het vak groeit, jonge $N. Ben je nu klaar om aan je echte lessen te beginnen? Ben je klaar om je plaats in te nemen in de geheime oorlog die wij voeren?$B$BZo ja, praat dan met Jennea Cannon in de Wizard's Sanctum in de magiërswijk van Stormwind. Ze heeft een taak voor je. Die opent je eerste venster op de onzichtbare wereld.",
  o = "Praat met Jennea Cannon in Stormwind.",
  c = "$N, ik heb een opdracht voor je, hier in de wijk van de $C. Luister goed, want we hebben geen tijd te verliezen.",
  g = { {"Meld je", "Report (zich melden)"}, {"kennis", "knowledge"}, {"vak", "craft, trade"}, {"groeit", "grows (groeien)"}, {"in te nemen", "to take (innemen)"}, {"voeren", "wage (a war)"}, {"venster", "window"}, {"onzichtbare", "invisible (onzichtbaar)"}, {"opdracht", "mission"}, {"wijk", "district"}, {"verliezen", "lose, waste"} },
