[1921] = { en = "Gathering Materials", tier = 1,
  t = "Materialen verzamelen",
  d = "Je hebt je collega-magiërs goed geholpen, en nu is het tijd om je tovenaarsgewaad aan te trekken. Wynne Larson kan je gewaad maken, maar je moet haar de materialen brengen.$B$BHet gewaad wordt van linnen gemaakt. Dat is makkelijk te vinden. Maar je hebt ook Charged Rift Gems nodig. De enige plek waar je die kunt vinden, is de Silver Stream Mine in Loch Modan. Daar heeft de bond van dwergenmijnwerkers ze in kratten achtergelaten.$B$BVerzamel het linnen en de stenen en breng ze naar Wynne Larson bij Larson Clothiers in de Mage District.",
  o = "Breng 10 Linen en de 6 Charged Rift Gems naar Wynne Larson in Stormwind.",
  p = "Hallo, $N. Jennea zei al dat je zou komen. Heb je iets voor me?",
  c = "Ja, dit zijn mooie stukken linnen. Ik kan er een prachtig gewaad van maken. En als ik de Charged Rift Gems erin heb geweven, hebben we een kledingstuk dat past bij een $C!",
  g = { {"collega-magiërs", "fellow mages"}, {"tovenaarsgewaad", "wizard's robe"}, {"gewaad", "robe"}, {"aan te trekken", "to put on (aantrekken)"}, {"linnen", "linen"}, {"bond", "league, union"}, {"dwergenmijnwerkers", "dwarven miners"}, {"kratten", "crates (krat)"}, {"achtergelaten", "left behind (achterlaten)"}, {"prachtig", "fine, beautiful"}, {"geweven", "woven (weven)"}, {"kledingstuk", "garment"} },
},

[1941] = { en = "Manaweave Robe", tier = 1,
  t = "De Manaweave Robe",
  c = "Hier is je gewaad. Het is een van de beste die ik ooit heb gemaakt! Draag het met trots. En als mensen ernaar vragen... zeg dan dat je het bij Larson Clothiers hebt gekregen!",
