[2039] = { en = "Find Bingles", tier = 1,
  t = "Zoek Bingles",
  d = "We hebben geen contact meer met Bingles! We stuurden hem op verkenning boven Gnomeregan. Hij heeft al meer dan een week niets gemeld. Ik weet het gewoon: hij heeft zichzelf opgeblazen.$B$BHet laatst zagen ze hem boven de Loch vliegen. Misschien kun jij het onderzoeken, $N.",
  o = "Zoek Bingles Blastenheimer in Loch Modan.",
  c = "Dus Gnoarn vertrouwt niet op mijn talent voor verkenning? Ik vraag me af waarom...$b$bLaat maar, ik heb je hulp nodig! Nee! De beweging heeft je hulp nodig!",
  g = { {"verkenning", "reconnaissance, scouting"}, {"gemeld", "reported (melden)"}, {"opgeblazen", "blown up (opblazen)"}, {"onderzoeken", "investigate"}, {"vertrouwt", "trusts (vertrouwen)"}, {"talent", "talent, ability"}, {"vraag me af", "wonder (zich afvragen)"}, {"Laat maar", "Never mind"}, {"beweging", "movement"} },
},

[1920] = { en = "Investigate the Blue Recluse", tier = 1,
  t = "Onderzoek de Blue Recluse",
  d = "Er is onrust gemeld in de Blue Recluse, de herberg in de Mage Quarter. Er lopen nu vreemde, onzichtbare wezens rond in de herberg. Ik ben bang dat daar een manascheur is ontstaan.$B$BIk wil dat je de herberg onderzoekt en die wezens vangt. Gebruik de Cantation of Manifestation in de herberg om de wezens zichtbaar te maken. Verzwak ze en gebruik dan een Containment Coffer om ze te vangen. Als je er genoeg hebt, kom dan terug naar mij met je volle kistjes, je lege kistjes en de Cantation.",
  o = "Haal een Cantation of Manifestation en een Chest of Containment Coffers achter Jennea Cannon vandaan. Breng 3 Filled Containment Coffers naar Jennea in de Wizard's Sanctum.",
  p = "Heb je de wezens gevangen, $n? We moeten ze bestuderen om uit te zoeken waarom ze hier zijn gekomen.",
  c = "Heel goed gedaan! Ik ga deze wezens bestuderen. Met ijver en geluk vind ik uit hoe ze in onze wereld zijn geglipt.$B$BJe wordt steeds waardevoller voor de gemeenschap van magiërs, $N.",
  g = { {"onrust", "disturbance"}, {"gemeld", "reported (melden)"}, {"herberg", "tavern, inn"}, {"onzichtbare", "invisible (onzichtbaar)"}, {"wezens", "creatures (wezen)"}, {"manascheur", "mana rift"}, {"ontstaan", "formed, arisen"}, {"zichtbaar", "visible"}, {"Verzwak", "Weaken, subdue (verzwakken)"}, {"kistjes", "small boxes, coffers (kistje)"}, {"bestuderen", "study"}, {"ijver", "diligence"}, {"geglipt", "slipped (glippen)"}, {"waardevoller", "more valuable (waardevol)"}, {"gemeenschap", "society, community"} },
},

[3370] = { en = "In Nightmares", tier = 2,
  t = "In nachtmerries",
  d = "Deze scherf bevat grote geheimen. Hij is de pure essentie van de Emerald Dream. Maar wat ik in deze scherf zie, is geen droom. Zo'n visioen zou je een nachtmerrie noemen.$B$BIk wil je niet ongerust maken, $N, maar ik denk dat het het beste is als je deze scherf zo snel mogelijk in de handen van een wijze druïde legt...$B$BJe moet Mathrengyl Bearwalker in de Cenarion Circle vinden. Ga naar Darnassus. Meer kan ik niet zeggen.",
  o = "Breng de Nightmare Shard naar Mathrengyl Bearwalker in Darnassus.",
  p = "Kan ik je ergens mee helpen?",
  c = "Heeft Falla je naar mij gestuurd? Nou, laten we die scherf eens bekijken. Je zegt dat ze er niet graag over praatte...$B$B<Mathrengyl kijkt aandachtig in de scherf>$B$BO... ik had niet... Nou ja.$B$B$N, bedankt dat je dit bij mij hebt gebracht. Maar ik raad je aan: praat niet over zulke dingen. Dat is niet verstandig. Dit zijn zaken waar alleen de Cenarion-druïden zich mee bezig moeten houden.$B$BLaten we zeggen dat de dingen in de Emerald Dream niet zijn zoals we dachten...$B$BMisschien kruisen onze wegen elkaar in de toekomst nog eens.",
  g = { {"scherf", "shard"}, {"bevat", "contains (bevatten)"}, {"essentie", "essence"}, {"visioen", "vision"}, {"nachtmerrie", "nightmare"}, {"ongerust", "worried, alarmed"}, {"druïde", "druid"}, {"aandachtig", "closely, attentively"}, {"raad je aan", "advise you (aanraden)"}, {"verstandig", "wise, sensible"}, {"zaken", "matters (zaak)"}, {"zich mee bezig moeten houden", "must deal with (zich bezighouden met)"}, {"kruisen", "cross (kruisen)"} },
},

[1939] = { en = "High Sorcerer Andromath", tier = 2,
  t = "High Sorcerer Andromath",
  d = "High Sorcerer Andromath wil met je praten, $N. Hij is boven in de Wizard's Sanctum, in de magiërswijk van Stormwind.$B$BHet is verstandig om met hem te praten, want Andromath is een van de machtigste magiërs die niet in Dalaran zijn opgesloten. Een gesprek met hem is echt een gesprek op hoog niveau.",
  o = "Praat met High Sorcerer Andromath.",
  c = "Gegroet, $N. Ik ben blij je te zien, en ik hoop dat je tijd hebt om te luisteren naar de woorden van een oude man...",
  g = { {"magiërswijk", "mage district"}, {"verstandig", "wise"}, {"machtigste", "most powerful (machtig)"}, {"opgesloten", "locked away (opsluiten)"}, {"gesprek", "conversation, council"}, {"op hoog niveau", "high-level"}, {"Gegroet", "Greetings"} },
},

[1940] = { en = "Pristine Spider Silk", tier = 2,
  t = "Smetteloze spinnenzijde",
  d = "Je dienst is nooit verslapt, $N. Ik denk dat het misschien tijd is voor een mooier kledingstuk, dat beter past bij je positie als ervaren magiër. Als je de materialen verzamelt, zorgen wij dat het gewaad gemaakt wordt.$B$BJe moet naar Duskwood gaan en op Carrion Recluse-spinnen jagen. Haal hun zijde eruit, maar alleen de beste, meest smetteloze zijde is goed genoeg. Als je genoeg hebt, breng het dan naar Wynne Larson, hier in de magiërswijk bij Larson Clothiers. Zij maakt je gewaad.",
  o = "Breng 8 Pristine Spider Silk naar Wynne Larson in Stormwind.",
  p = "Ah, ja. De magiërs van de Wizard's Sanctum zeiden al dat je met me zou komen praten. Heb je de zijde die nodig is?",
  c = "Mooie exemplaren zijn dit. Ik ga meteen aan het werk!",
  g = { {"Smetteloze", "pristine, flawless (smetteloos)"}, {"spinnenzijde", "spider silk"}, {"dienst", "service"}, {"verslapt", "slackened, wavered (verslappen)"}, {"kledingstuk", "garment"}, {"positie", "station, position"}, {"ervaren", "experienced, adept"}, {"gewaad", "robe"}, {"jagen", "hunt"}, {"zijde", "silk"}, {"exemplaren", "specimens (exemplaar)"}, {"meteen", "right away"} },
},

[1942] = { en = "Astral Knot Garment", tier = 2,
  t = "Het Astral Knot Garment",
  c = "Je kledingstuk is klaar! En die zijde die je verzamelde was zo mooi... je vindt het toch niet erg dat ik het een beetje kort heb gemaakt, zodat ik wat zijde voor mezelf overhield?$B$BIk maak maar een grapje. Het past je prima, en het is perfect voor avonturen en voor een chic diner. Veel plezier!",
  g = { {"kledingstuk", "garment"}, {"zijde", "silk"}, {"niet erg", "don't mind"}, {"overhield", "had left over (overhouden)"}, {"grapje", "joke"}, {"avonturen", "adventures (avontuur)"}, {"chic", "formal, smart"}, {"diner", "dinner, dining"} },
},

[1938] = { en = "Ur's Treatise on Shadow Magic", tier = 2,
  t = "Ur's Treatise on Shadow Magic",
  d = "Lang geleden studeerden drie magiërs in deze toren, totdat een van hen zich overgaf aan de duistere kunsten. Ze vroegen hem dringend om zich van die kwade magie af te keren, maar hij kon het niet weerstaan. Daarom werd hij verbannen.$B$BHet nieuwe gebied van de gevallen magiër is de toren van Ilgalar in Redridge. Hij nam een machtig boek mee: Ur's Treatise on Shadow Magic.$B$BWij, de magiërs van Stormwind, willen dat boek terug. Ga de toren van Ilgalar binnen, zoek het boek in zijn bibliotheek en breng het naar mij.",
  o = "Breng Ur's Treatise on Shadow Magic naar High Sorcerer Andromath in Stormwind.",
  p = "Heb je het boek, $N? De geheimen erin zijn niet bedoeld voor wie geen opleiding heeft. Wie er diep in duikt, kan eindigen in ondergang en verderf.",
  c = "Ik was bang dat Morganth het boek ergens anders had verstopt, of dat hij een manier had gevonden om het te openen en te lezen.$B$BHet is goed om te zien dat dat niet zo is, en dat de zegels die wij op Ur's Treatise on Shadow Magic hebben gezet nog steeds werken.",
  g = { {"overgaf", "gave in, fell (zich overgeven)"}, {"duistere kunsten", "dark arts"}, {"dringend", "urgently"}, {"kwade", "evil (kwaad)"}, {"af te keren", "to turn away (zich afkeren)"}, {"weerstaan", "resist"}, {"verbannen", "banished (verbannen)"}, {"gebied", "domain, territory"}, {"gevallen", "fallen (vallen)"}, {"bibliotheek", "library"}, {"bedoeld", "meant (bedoelen)"}, {"opleiding", "training"}, {"duikt", "delves, dives (duiken)"}, {"ondergang", "doom, downfall"}, {"verderf", "ruin, corruption"}, {"zegels", "seals (zegel)"} },
},

[637] = { en = "Sully Balloo's Letter", tier = 2,
  t = "De brief van Sully Balloo",
  d = "De doorweekte envelop is beschadigd door de oorlog en valt in je handen uit elkaar. Je houdt nog een paar bladzijden van een brief vast. Hij is heel zorgvuldig geschreven.$b$bDe brief is gericht aan mevrouw Sara Balloo uit Ironforge en begint met: “Mijn lieve Sara....”",
  o = "Bezorg Sully Balloo's Letter bij Sara Balloo.",
  p = "Je ziet eruit alsof je een lange reis hebt gemaakt en in je tijd veel onrust hebt gezien, $C. De tijden waarin we leven zijn zwaar voor de ziel. Welk nieuws breng je me nu?",
  c = "Zeg je dat je mijn Sully onder het ijskoude water hebt zien liggen, vastgeklemd? Zeg dat het niet waar is!$B$BLaat me lezen wat hij heeft geschreven....",
  g = { {"doorweekte", "waterlogged, soaked"}, {"envelop", "envelope"}, {"beschadigd", "damaged (beschadigen)"}, {"valt", "falls (vallen)"}, {"uit elkaar", "apart"}, {"bladzijden", "pages (bladzijde)"}, {"zorgvuldig", "carefully"}, {"gericht aan", "addressed to"}, {"Bezorg", "Deliver (bezorgen)"}, {"onrust", "turmoil, unrest"}, {"ziel", "soul"}, {"ijskoude", "icy"}, {"vastgeklemd", "pinned, trapped (vastklemmen)"} },
},

[683] = { en = "Sara Balloo's Plea", tier = 2,
  t = "Het verzoek van Sara Balloo",
  d = "$n, ik heb maar een klein verzoek voor je.$b$bNeem dit briefje dat ik heb geschreven mee naar onze grote vorst van Ironforge, koning Magni Bronzebeard. Het is maar een kleine taak voor iemand zoals jij. Je hebt tot nu toe veel moed getoond voor de zaak van de Alliance.$b$bAls ik in mijn verdriet zelf voor de koning verschijn, help ik mijn zaak niet. Dat begrijp je vast wel.",
  o = "Breng het briefje van Sara Balloo naar King Magni Bronzebeard van Ironforge.",
  p = "Dus jij bent $N de $C? Het nieuws over wat je voor de Alliance hebt gedaan is ver gekomen, wist je dat?$B$BMet welke zaak kom je vandaag voor mij?",
  c = "Het duurt maar even voordat ik deze brief heb doorgelezen...",
  g = { {"verzoek", "request, plea"}, {"briefje", "note"}, {"vorst", "monarch"}, {"taak", "task"}, {"moed", "courage, valor"}, {"getoond", "shown (tonen)"}, {"zaak", "cause, business"}, {"verdriet", "grief, sorrow"}, {"verschijn", "appear (verschijnen)"}, {"vast wel", "surely"}, {"doorgelezen", "read through (doorlezen)"} },
},

[686] = { en = "A King's Tribute", tier = 2,
  t = "Een eerbetoon van de koning",
  d = "Ik verwacht niet dat goede dwergen zoals mevrouw Balloo begrijpen waarom we de gruwelen van de oorlog moeten verdragen voor het welzijn van ons volk. Het verlies van haar man, en het verlies van elke dwerg die vecht in naam van de Alliance, weegt zwaar op mijn ziel.$b$bIk kan haar man niet terugbrengen uit de Twisting Nether, maar ik kan hem wel eren.$b$bIk ga Grand Mason Marblesten de opdracht geven om een monument voor Sully Balloo te bouwen.$b$bStuur hem nu bericht, $c. Jij zorgt dat mijn opdracht wordt uitgevoerd.",
  o = "King Magni Bronzebeard wil dat je met Grand Mason Marblesten praat.",
  c = "Dus koning Magni Bronzebeard heeft je zelf gestuurd?$B$BNou, nou! Dit moet belangrijk zijn!",
  g = { {"eerbetoon", "tribute"}, {"gruwelen", "horrors, travesties"}, {"verdragen", "endure, bear"}, {"welzijn", "well-being, good"}, {"verlies", "loss"}, {"weegt zwaar", "weighs heavy (zwaar wegen)"}, {"eren", "honour"}, {"opdracht", "commission, order"}, {"monument", "memorial"}, {"bericht", "message, word"}, {"uitgevoerd", "carried out (uitvoeren)"} },
},

[1950] = { en = "Get the Scoop", tier = 2,
  t = "Zoek het uit",
  d = "Ik kan je helpen met het boek, maar eerst moet jij mij helpen!$B$BHet boek dat je zoekt, ligt in mijn kluis, die met magie op slot zit. Om hem te openen, moet je een speciale zin uitspreken, en ik weet die zin niet meer! Normaal helpt mijn assistent me om zulke dingen te onthouden, maar hij is nergens te vinden.$B$BAls je mijn boek wilt, zoek dan mijn leerling! Vraag rond bij de racebaan. Als je geluk hebt, heeft iemand hem gezien. Sleep hem hierheen, of krijg in elk geval mijn magische zin van hem, zodat we mijn kist kunnen openen!",
  o = "Zoek de zin voor de kluis van Tirth en ga dan terug naar Tirth.",
  p = "Waar wacht je op? Ik heb mijn magische zin nodig!",
  c = "Ah, nu weet ik het weer...$B$BIk was die kleine vloek vergeten die ik op Johnson had gelegd. Ik weet niet meer waarom ik het deed, maar ik weet zeker dat hij het verdiende, die ondankbare kleine!",
  e = "Geheime zin gevonden",
  g = { {"Zoek het uit", "Find out, get the scoop (uitzoeken)"}, {"kluis", "strongbox, safe"}, {"op slot", "locked"}, {"uitspreken", "utter, say"}, {"onthouden", "remember"}, {"leerling", "apprentice"}, {"Vraag rond", "Ask around (rondvragen)"}, {"racebaan", "race track"}, {"Sleep", "Drag (slepen)"}, {"in elk geval", "at least"}, {"vloek", "curse"}, {"verdiende", "deserved (verdienen)"}, {"ondankbare", "ungrateful (ondankbaar)"} },
},

[689] = { en = "A King's Tribute", tier = 2,
  t = "Een eerbetoon van de koning",
  d = "Dus onze goede koning wil een monument laten bouwen ter ere van een soldaat die Sully Balloo heette? En je zegt dat de arme kerel is gestorven bij de ramp van de Thandol Span?$b$bBah, komt er ooit vrede op Azeroth?$b$bToch is elke opdracht van de koning uiterst belangrijk. Ik wil een echt groots werk maken dat lang blijft staan. Daarvoor wil ik met een van de beste stenen werken die er zijn. Reis naar Darrow Hill in Hillsbrad en verzamel wat Alterac Granite voor me.",
  o = "Grand Mason Marblesten van Ironforge wil 5 stukken Alterac Granite.",
  p = "$N, $N, $N! Zeg me dat je genoeg Alterac Granite hebt, zodat ik kan beginnen aan mijn meesterwerk ter ere van Sully Balloo.",
  c = "Perfect! Beter dan ik me had kunnen voorstellen!$B$BEn ik heb best veel fantasie, weet je...",
  g = { {"ter ere van", "in honour of"}, {"kerel", "chap, fellow"}, {"ramp", "disaster, tragedy"}, {"Toch", "Nonetheless, still"}, {"uiterst", "extremely, utmost"}, {"groots", "grand, epic"}, {"verzamel", "gather (verzamelen)"}, {"stukken", "pieces (stuk)"}, {"meesterwerk", "masterpiece"}, {"voorstellen", "imagine (zich voorstellen)"}, {"fantasie", "imagination"} },
},

[700] = { en = "A King's Tribute", tier = 2,
  t = "Een eerbetoon van de koning",
  d = "Ah, wat een mooie steen komt er uit Lordaeron. Zo jammer dat dat land zo'n puinhoop is.$b$bMaar het monument is heel goed gelukt! Ik denk dat de koning er erg blij mee zal zijn.$b$bWil je nu aan Zijne Majesteit laten weten dat het monument klaar is, zoals hij vroeg?",
  o = "Breng verslag uit bij King Magni Bronzebeard.",
  c = "Het graniet lijkt maar een klein gebaar vergeleken met het leven van een grote dwerg. Maar geen enkele dwerg blijft voor eeuwig op deze planeet.$B$BLaten we hopen dat het monument blijft staan als herinnering voor iedereen die in de toekomst over het grote Azeroth zal lopen. Laten we niet vergeten dat dappere soldaten zoals Sully Balloo juist voor hen zo moedig hun leven hebben gegeven.",
  g = { {"jammer", "a shame, a pity"}, {"puinhoop", "shambles, mess"}, {"gelukt", "turned out well (lukken)"}, {"Zijne Majesteit", "His Majesty"}, {"Breng verslag uit", "Report (verslag uitbrengen)"}, {"graniet", "granite"}, {"gebaar", "gesture, token"}, {"vergeleken met", "compared to"}, {"eeuwig", "eternity, forever"}, {"herinnering", "reminder, memory"}, {"dappere", "brave (dapper)"}, {"moedig", "valiantly, bravely"} },
},

[1453] = { en = "Reclaimers' Business in Desolace", tier = 2,
  t = "Werk voor de Reclaimers in Desolace",
  d = "Er is werk te doen in Desolace, $N. Het is een vreselijke plek, vervuild door centauren en ander naar gespuis. Maar als je een week eerlijk werk zoekt, ga er dan heen. Zoek Kreldig Ungor op en zeg hem dat ik je heb gestuurd.$B$BHij zit verstopt in Nijel's Point. Dat is een klein, gezellig kamp, verborgen in de bergen van het noorden van Desolace. Ga gewoon naar het oosten als je er vanuit de Stonetalon Mountains binnenkomt. Je ziet het makkelijk over het hoofd, dus let goed op.",
  o = "Praat met Kreldig Ungor in Desolace.",
  c = "Fijn om te zien dat de Reclaimers genoeg werk hebben, en genoeg avonturiers die willen helpen.$B$BIk ben Kreldig, $N. Het was slim van je om de Reclaimers te helpen. Iedereen heeft tegenwoordig wel iets nodig: ze zijn een erfstuk van de familie kwijt, een magisch voorwerp, een geliefde. Je weet het nooit. Maar met de Reclaimers in de buurt kan iedereen terugvinden wat hij kwijt is, voor de juiste prijs.",
  g = { {"vreselijke", "atrocious, terrible (vreselijk)"}, {"vervuild", "befouled, polluted (vervuilen)"}, {"centauren", "centaurs (centaur)"}, {"naar gespuis", "nasty riff-raff, nasties"}, {"eerlijk", "honest"}, {"verstopt", "hidden, holed up (verstoppen)"}, {"gezellig", "cozy"}, {"verborgen", "hidden (verbergen)"}, {"ziet het over het hoofd", "miss it, overlook it (over het hoofd zien)"}, {"avonturiers", "adventurers (avonturier)"}, {"tegenwoordig", "these days"}, {"erfstuk", "heirloom"}, {"voorwerp", "item, object"}, {"geliefde", "loved one"} },
},

[2948] = { en = "Gnome Improvement", tier = 2,
  t = "Gnomische verbetering",
  d = "Luister, $n, die ring is van jou, dat klopt... maar ik kan een betere voor je maken! Zoals ik al zei, is dat ontwerp heel simpel. Ik ben nu veel handiger, en voor maar dertig zilverstukken maak ik hem mooier voor je! Nou ja, eigenlijk iets meer dan dertig...$B$BIk zit nu even krap: mijn voorraad materiaal is helemaal op. Als je me een staaf zilver en een mosagaat brengt, maak ik een rooster van zilver en agaat op de ring. Dan heeft hij wat meer pit!$B$BVertrouw me maar!",
  o = "Breng de Brilliant Gold Ring, een Silver Bar, een Moss Agate en 30 zilverstukken naar Talvash del Kissel in Ironforge.",
  p = "Heb je de materialen die ik nodig heb? Ik zou er niet om vragen als ik niet zo'n pech had...",
  c = "Ah, precies wat ik nodig had! Ooit, als ik uit dit gat ben waar ik onterecht in zit, maak ik voor jou, voor IEDEREEN, de mooiste sieraden van heel Azeroth! Tot die tijd: bedankt dat je zo sportief bent met de grondstoffen. Normaal vraag ik tien keer zoveel als ik jou heb gevraagd voor een ring van deze kwaliteit...$B$BOver ringen gesproken: hier is je nieuwe!",
  g = { {"ontwerp", "design"}, {"handiger", "more skilled (handig)"}, {"zilverstukken", "silver coins (zilverstuk)"}, {"krap", "tight (for money)"}, {"voorraad", "stock, supply"}, {"staaf", "bar"}, {"mosagaat", "moss agate"}, {"rooster", "lattice, grid"}, {"pit", "pizzazz, spirit"}, {"pech", "bad luck"}, {"onterecht", "unjustly"}, {"sieraden", "jewellery, trinkets (sieraad)"}, {"sportief", "sporting, a good sport"}, {"grondstoffen", "materials, reagents (grondstof)"} },
},

[707] = { en = "Ironband Wants You!", tier = 3,
  t = "Ironband heeft je nodig!",
  d = "$N. Ik heb berichten gekregen van Prospector Ironband bij zijn opgravingsplaats in Loch Modan. Hij heeft iemand nodig die wat loopwerk doet voor een andere opgraving van ons.$B$BMeer weet ik niet, maar als je je benen wilt strekken, ga dan met Ironband praten.",
  o = "Praat met Prospector Ironband bij Ironband's Excavation Site in Loch Modan.",
  c = "Dus Stormpike heeft je gestuurd? Mooi.$B$BIk heb een grote taak voor je...",
  g = { {"berichten", "reports, messages (bericht)"}, {"opgravingsplaats", "excavation site"}, {"loopwerk", "legwork"}, {"opgraving", "excavation, dig"}, {"strekken", "stretch"}, {"taak", "task"} },
},

[1714] = { en = "Essence of the Exile", tier = 3,
  t = "Essentie van de verbannene",
  p = "De ketel borrelt. De dampen lokken je...",
  c = "De amuletten zinken langzaam naar de bodem van de ketel...$B$BEen grote bel stijgt op naar het oppervlak van de vloeistof en knapt...$B$B...En er verschijnt een kolkende klomp gesmolten steen.",
  g = { {"verbannene", "exile (person)"}, {"ketel", "cauldron"}, {"borrelt", "bubbles (borrelen)"}, {"dampen", "vapours (damp)"}, {"lokken", "beckon, lure"}, {"amuletten", "charms (amulet)"}, {"zinken", "sink"}, {"bodem", "bottom, depths"}, {"bel", "bubble"}, {"stijgt op", "rises (opstijgen)"}, {"oppervlak", "surface"}, {"vloeistof", "liquid"}, {"knapt", "breaks, pops (knappen)"}, {"kolkende", "churning (kolken)"}, {"gesmolten", "molten (smelten)"} },
