[1947] = { en = "Journey to the Marsh", tier = 3,
  t = "Reis naar het moeras",
  d = "Nu is het tijd om je toverstok als magiër te verdienen. Om aan deze opdracht te beginnen, praat je met Tabetha, de menselijke kluizenares in Dustwallow Marsh. Je vindt haar hut diep in het moeras, ten westen van Theramore.$B$BPraat met haar, want haar kennis is enorm. Je vindt het huisje van Tabetha ten westen van Theramore, net ten noorden van de Stonemaul Ruins.",
  o = "Praat met Tabetha.",
  c = "Stil! Ik ben op een lastig punt en mag niet gestoord worden!$B$BEén momentje...",
  g = { {"moeras", "marsh"}, {"toverstok", "wand"}, {"verdienen", "earn"}, {"menselijke", "human (menselijk)"}, {"kluizenares", "hermit (f.)"}, {"hut", "shack, hut"}, {"enorm", "vast, enormous"}, {"huisje", "cottage"}, {"lastig punt", "delicate juncture"}, {"gestoord", "disturbed (storen)"} },
},

[1661] = { en = "The Tome of Nobility", tier = 3,
  t = "De Tome of Nobility",
  d = "Ik groet je opnieuw, $N. Ik ben trotser dan ooit om je mijn $gbroeder:zuster; te noemen. Jouw toewijding is een eer voor ons allemaal.$B$BHet is tijd dat ik je een groot geschenk geef. Maar weet dit: nu geef ik het je zomaar, maar later, als er tijd voor is, wordt dit een veel grotere uitdaging voor alle paladijnen die aan mijn opdracht beginnen.$B$BPraat nog eens met me, dan geef ik je een grote gunst.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Gefeliciteerd, en moge het Licht je beschermen.",
  g = { {"groet", "greet (groeten)"}, {"trotser", "prouder (trots)"}, {"toewijding", "dedication"}, {"eer", "honour, tribute"}, {"geschenk", "gift"}, {"zomaar", "freely, just like that"}, {"uitdaging", "challenge"}, {"paladijnen", "paladins (paladijn)"}, {"gunst", "favour, boon"}, {"Gefeliciteerd", "Congratulations"}, {"moge", "may (mogen)"} },
},

[1712] = { en = "Cyclonian", tier = 3,
  t = "Cyclonian",
  d = "Ik heb deze plek eeuwenlang in de gaten gehouden. Ik kijk, zodat ik op een dag de grote Cyclonian zie vallen. Maar ik heb nog geen kampioen gevonden die de heer van de wind kan verslaan.$B$BMisschien ben jij die kampioen.$B$BBewijs het me. Verzamel de voorwerpen die ik nodig heb om Cyclonian op te roepen. Dan weet ik dat je een groot krijger bent. Misschien kun je hem dan verslaan en zijn wervelwindhart veroveren.$B$BAls dat lukt, breng ik de kracht van het hart over in een wapen, en dat wapen geef ik aan jou.$B$BHier is een perkament met de voorwerpen die ik nodig heb.",
  o = "Breng de voorwerpen op Bath'rah's Parchment naar Bath'rah the Windwatcher in Alterac.",
  p = "Heb je de voorwerpen, $N? Als je ze verzamelt, is dat het bewijs dat ik nodig heb: dan weet ik dat je sterk genoeg bent om Cyclonian onder ogen te komen.",
  c = "Je hebt de voorwerpen voor mijn spreuk verzameld en me je kracht en sluwheid getoond. Maar de volgende stap van onze opdracht is nog gevaarlijker.$b$bLaten we hopen dat je kracht je niet in de steek laat.",
  g = { {"eeuwenlang", "for ages"}, {"in de gaten gehouden", "watched, kept an eye on (in de gaten houden)"}, {"kampioen", "champion"}, {"verslaan", "defeat"}, {"Bewijs", "Prove (bewijzen); proof"}, {"op te roepen", "to summon (oproepen)"}, {"wervelwindhart", "whirlwind heart"}, {"veroveren", "win, conquer"}, {"breng ... over", "transfer, infuse (overbrengen)"}, {"perkament", "parchment"}, {"onder ogen te komen", "to face (onder ogen komen)"}, {"spreuk", "spell"}, {"sluwheid", "cunning"}, {"in de steek laat", "fails, lets down (in de steek laten)"} },
},

[1713] = { en = "The Summoning", tier = 3,
  t = "De oproeping",
  d = "Ik ben klaar om het ritueel uit te voeren om Cyclonian op te roepen. Als hij is opgeroepen, moet je hem verslaan en zijn wervelwindhart nemen. Dat gebruik ik om een wapen te vullen met de kracht van Cyclonian.$B$B$N, ben je klaar om de heer van de wind onder ogen te komen?",
  o = "Breng het Whirlwind Heart naar Bath'rah Windwatcher.",
  p = "$N, ik moet het wervelwindhart hebben!",
  c = "Het is je gelukt! Je hebt Cyclonian verslagen en het Whirlwind Heart gekregen!",
  g = { {"oproeping", "summoning"}, {"ritueel", "ritual"}, {"uit te voeren", "to perform (uitvoeren)"}, {"opgeroepen", "summoned (oproepen)"}, {"wervelwindhart", "whirlwind heart"}, {"vullen", "fill, instill"}, {"onder ogen te komen", "to face (onder ogen komen)"}, {"verslagen", "defeated (verslaan)"} },
},

[1792] = { en = "Whirlwind Weapon", tier = 3,
  t = "Wervelwindwapen",
  c = "Ik heb het wervelwindhart en ben klaar om het in het voorwerp van jouw keuze te plaatsen.$B$BKies je wapen, $N, en weet dat zijn kracht de kracht van Cyclonian is.",
  g = { {"Wervelwindwapen", "whirlwind weapon"}, {"wervelwindhart", "whirlwind heart"}, {"voorwerp", "object, vessel"}, {"keuze", "choice"}, {"plaatsen", "place, put"}, {"kracht", "power"} },
},

[4485] = { en = "The Tome of Nobility", tier = 3,
  t = "De Tome of Nobility",
  d = "Hallo, $N. Ik zie dat je toewijding sterk blijft, net als je geloof.$B$BIk denk dat het tijd is om met Duthorian Rall in Stormwind te praten. Er zijn nog meer lessen voor je, en ik denk dat je er klaar voor bent.$B$BZoek hem op in de Cathedral of Light, en $N, neem deze lessen serieus. Je hebt je positie bereikt door nederigheid en hard werken. Stel ons niet teleur door arrogant te worden.$B$BHet ga je goed.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Ah, je bent terug in de kathedraal, $n. Mooi. Er is de laatste tijd veel gebeurd, en ik wil je hulp vragen als je het waard blijkt.$b$bEr zijn veel verraderlijke vijanden in de buurt. Ik heb je hulp nodig om ze te stoppen.",
  g = { {"toewijding", "dedication"}, {"geloof", "faith"}, {"serieus", "seriously"}, {"positie", "status, position"}, {"bereikt", "attained (bereiken)"}, {"nederigheid", "humility"}, {"Stel ... niet teleur", "don't disappoint (teleurstellen)"}, {"arrogant", "arrogant"}, {"Het ga je goed", "Be well, farewell"}, {"kathedraal", "cathedral"}, {"waard", "worthy"}, {"blijkt", "proves (blijken)"}, {"verraderlijke", "treacherous (verraderlijk)"} },
},

[4486] = { en = "The Tome of Nobility", tier = 3,
  t = "De Tome of Nobility",
  d = "Zo, zo, zo, kijk eens naar de machtige paladijn in al $gzijn:haar; pracht.$B$BSorry, $N, ik bedoelde het niet beledigend... Ik word soms gewoon een beetje jaloers als ik sommige van je prestaties zie. Tiza zegt dat het mijn zwakke punt is, en ik heb haar beloofd dat ik eraan zou werken. Het is soms gewoon moeilijk, snap je?$B$BMaar ik wilde met je praten omdat Duthorian Rall in Stormwind een bericht heeft gestuurd. Hij wil je in de Cathedral of Light zien als je klaar bent. Het klonk belangrijk. Het klonk alsof er iets aan de hand is.",
  o = "Praat met Duthorian Rall in Stormwind.",
  c = "Ah, je bent terug in de kathedraal, $n. Mooi. Er is de laatste tijd veel gebeurd, en ik wil je hulp vragen als je het waard blijkt.$b$bEr zijn veel verraderlijke vijanden in de buurt. Ik heb je hulp nodig om ze te stoppen.",
  g = { {"machtige", "mighty (machtig)"}, {"pracht", "splendour, regality"}, {"beledigend", "offensive, insulting"}, {"jaloers", "jealous"}, {"prestaties", "feats, achievements (prestatie)"}, {"zwakke punt", "weakness, weak spot"}, {"beloofd", "promised (beloven)"}, {"klonk", "sounded (klinken)"}, {"aan de hand", "going on"}, {"kathedraal", "cathedral"}, {"waard", "worthy"}, {"verraderlijke", "treacherous (verraderlijk)"} },
},

})

